// One item per page: the live URL and the route it becomes in Next.js.
return [
  { json: { url: 'https://www.allbirds.com', route: '/' } }
];

// One item per section still to extract: every section MiroMiro listed on each
// page, except the one the first call already returned.
const norm = (u) => String(u || '').replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '')
const pages = $('List Pages to Migrate').all().map((i) => i.json)
const out = []
for (const item of $input.all()) {
  const page = item.json
  const route = (pages.find((p) => norm(p.url) === norm(page.url)) || {}).route || '/'
  for (const s of (page.sections || []).slice(0, 15)) {
    if (s.selector === page.selector) continue
    out.push({ json: { url: page.url, route, selector: s.selector, label: s.label, order: s.order } })
  }
}
// A site with only heroes still finishes: the next node repeats a cached (free) hero call.
if (!out.length) return [{ json: { url: $input.first().json.url } }]
return out

// Turns every extracted section into a Next.js (App Router) project:
// one component per section, one page per route with the sections in page
// order, Tailwind CSS 4, and the sections' @keyframes in globals.css.
const norm = (u) => String(u || '').replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '')
const pages = $('List Pages to Migrate').all().map((i) => i.json)
const first = $('Extract Hero and Find Sections').all().map((i) => i.json)
const rest = $input.all().map((i) => i.json)
const routeOf = (url) => (pages.find((p) => norm(p.url) === norm(url)) || {}).route || '/'
const orderOf = (url, selector) => {
  const page = first.find((f) => norm(f.url) === norm(url))
  const s = page && (page.sections || []).find((x) => x.selector === selector)
  return s && s.order ? s.order : 999
}
const pascal = (s) => (s.replace(/(^|[^a-zA-Z0-9]+)([a-zA-Z0-9])/g, (_, __, c) => c.toUpperCase()) || 'Home').replace(/^[0-9]/, 'P$&')

const byRoute = {}
const seen = new Set()
const failed = rest.filter((r) => !r.code).length
for (const r of [...first, ...rest]) {
  if (!r.code) continue
  const key = norm(r.url) + '|' + r.selector
  if (seen.has(key)) continue
  seen.add(key)
  const route = routeOf(r.url)
  if (!byRoute[route]) byRoute[route] = []
  byRoute[route].push({ code: r.code, css: r.css || '', order: orderOf(r.url, r.selector) })
}

const files = {}
const keyframes = new Set()
for (const [route, sections] of Object.entries(byRoute)) {
  sections.sort((a, b) => a.order - b.order)
  const slug = route === '/' ? 'home' : route.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '')
  const imports = []
  const tags = []
  sections.forEach((s, i) => {
    const name = `${pascal(slug)}Section${String(i + 1).padStart(2, '0')}`
    const code = s.code.replace(/export default function [A-Za-z0-9_]+/, `export default function ${name}`)
    files[`components/${slug}/${name}.jsx`] = code
    imports.push(`import ${name} from '@/components/${slug}/${name}'`)
    tags.push(`      <${name} />`)
    for (const block of s.css.split(/\n(?=@keyframes)/)) {
      if (block.includes('@keyframes')) keyframes.add(block.replace(/^\/\*[^*]*\*\/\s*/, '').trim())
    }
  })
  const dir = route === '/' ? 'app' : `app${route.replace(/\/+$/, '')}`
  files[`${dir}/page.jsx`] = `${imports.join('\n')}\n\nexport default function Page() {\n  return (\n    <main>\n${tags.join('\n')}\n    </main>\n  )\n}\n`
}

const kf = keyframes.size ? `\n/* Animations used by the migrated sections */\n${[...keyframes].join('\n\n')}\n` : ''
files['app/globals.css'] = `@import "tailwindcss";\n${kf}`
files['app/layout.jsx'] = `import './globals.css'\n\nexport const metadata = { title: 'Migrated site' }\n\nexport default function RootLayout({ children }) {\n  return (\n    <html lang="en">\n      <body>{children}</body>\n    </html>\n  )\n}\n`
files['jsconfig.json'] = JSON.stringify({ compilerOptions: { paths: { '@/*': ['./*'] } } }, null, 2) + '\n'
files['postcss.config.mjs'] = `export default { plugins: { '@tailwindcss/postcss': {} } }\n`
files['next.config.mjs'] = `/** @type {import('next').NextConfig} */\nexport default { images: { unoptimized: true } }\n`
files['package.json'] = JSON.stringify({
  name: 'migrated-site',
  private: true,
  scripts: { dev: 'next dev', build: 'next build', start: 'next start' },
  dependencies: { next: '^15.5.0', react: '^19.1.0', 'react-dom': '^19.1.0' },
  devDependencies: { tailwindcss: '^4.1.0', '@tailwindcss/postcss': '^4.1.0' }
}, null, 2) + '\n'
files['README.md'] = [
  '# Migrated site',
  '',
  'Generated by MiroMiro (https://miromiro.app/api) from:',
  ...pages.map((p) => `- ${p.url} -> ${p.route}`),
  '',
  '```bash',
  'npm install',
  'npm run dev',
  '```',
  '',
  'Review before launch:',
  '- Text and images still come from the source site: replace them unless it is your own site, and download the images into /public before the old site goes offline.',
  '- Menus, sliders, forms and carts arrive as static markup: wire them up in React.',
  '- Load the site\'s fonts (next/font or @font-face): the classes name them but do not include the files.',
  ''
].join('\n')

const binary = {}
const keys = []
Object.entries(files).forEach(([path, content], i) => {
  const key = `file${i}`
  keys.push(key)
  binary[key] = { data: Buffer.from(content, 'utf8').toString('base64'), mimeType: 'text/plain', fileName: path }
})
return [{ json: { files: Object.keys(files), failed, binaryKeys: keys.join(',') }, binary }]
